const products=window.SS_PRODUCTS;
const goal=(window.SS_GOALS||[]).find(g=>location.pathname===`/goals/${g.slug}/`);
let cart={};try{const saved=JSON.parse(localStorage.getItem('ss-bag-v1')||'{}');for(const p of products)if(Number.isInteger(saved[p.id])&&saved[p.id]>0)cart[p.id]=Math.min(saved[p.id],99)}catch{}const params=new URLSearchParams(location.search);let filter=['All','Whey','Isolate','Creatine','Premium'].includes(params.get('category'))?params.get('category'):'All',brand=products.some(p=>p.brand===params.get('brand'))?params.get('brand'):'',query='';const $=s=>document.querySelector(s);const productDialog=$('#product-dialog'),cartDialog=$('#cart-dialog');
function render(){if(!$('#products'))return;const shown=products.filter(p=>(!goal||goal.ids.includes(p.id))&&(filter==='All'||(filter==='Premium'?p.premium:p.category===filter))&&(!brand||p.brand===brand)&&(`${p.brand} ${p.name} ${p.type}`.toLowerCase().includes(query)));$('#products').innerHTML=shown.length?shown.map(p=>`<article class="product-card" style="--card-tone:${p.color};--card-accent:${p.accent}"><a class="product-image" href="/products/${p.slug}/" aria-label="View ${p.name}"><span class="tag">${p.tag}</span><span class="pack-depth"><img src="${p.image}" alt="${p.brand} ${p.name}" loading="lazy" width="260" height="300"></span><span class="card-explore">Explore product ↗</span></a><div class="card-brand">${p.brand}</div><h3><a href="/products/${p.slug}/">${p.name}</a></h3><div class="card-meta">${p.type}</div><div class="card-bottom"><span>Enquire for price</span><button class="add-btn" data-add="${p.id}">Add to bag +</button></div></article>`).join(''):'<p class="no-results">No supplements match your search. Try another brand or clear your filters.</p>';$('#active-brand').innerHTML=brand?`${brand}<button id="clear-brand">Clear brand ×</button>`:'';document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))});if($('#catalog-count'))$('#catalog-count').textContent=String(goal?goal.ids.length:products.length).padStart(2,'0');document.dispatchEvent(new Event('ss:catalog'))}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function save(){try{localStorage.setItem('ss-bag-v1',JSON.stringify(cart))}catch{}$('#cart-count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);renderCart()}
function add(id,count=1){if(!products.some(p=>p.id===id))return;cart[id]=Math.min((cart[id]||0)+count,99);save();notify('Added to your bag. View Bag to enquire.')}
function detail(id){const p=products.find(p=>p.id===id);if(p)location.href='/products/'+p.slug+'/';}
function renderCart(){const items=products.filter(p=>cart[p.id]);const markup=items.length?items.map(p=>`<div class="cart-item"><img src="${p.image}" alt="${p.name}"><div><small>${p.brand}</small><h3>${p.name}</h3><div class="quantity"><button data-minus="${p.id}" aria-label="Decrease ${p.name} quantity">−</button><span>${cart[p.id]}</span><button data-plus="${p.id}" aria-label="Increase ${p.name} quantity">+</button><button class="remove" data-remove="${p.id}">Remove</button></div></div></div>`).join(''):'<div class="empty"><h3>Your next level starts with a choice.</h3><p>Your bag is empty. Explore the shelf and add a protein to enquire about.</p><button class="button dark" data-continue-shop>Explore proteins ↗</button></div>';$('#cart-items').innerHTML=markup;if($('#bag-page-items'))$('#bag-page-items').innerHTML=markup;const message='Hi S&S! I would like to enquire about:\n'+items.map(p=>`${cart[p.id]} × ${p.brand} ${p.name}`).join('\n')+'\nPlease confirm availability, pack sizes, flavours and prices. Thank you!';const bottom=items.length?`<p class="cart-note">Ready to find your fit? Send your selection to the store to confirm availability and prices. This is an enquiry, not a paid order.</p><a class="button dark cart-send" href="https://wa.me/917022825588?text=${encodeURIComponent(message)}" target="_blank" rel="noopener">Enquire on WhatsApp ↗</a><p class="cart-note">Prefer to talk? <a href="tel:+917022825588"><u>Call +91 70228 25588</u></a></p>`:'';$('#cart-bottom').innerHTML=bottom;if($('#bag-page-bottom'))$('#bag-page-bottom').innerHTML=bottom}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.detail)detail(b.dataset.detail);if(b.dataset.add)add(b.dataset.add);if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.brand){brand=b.dataset.brand;filter='All';query='';$('#search').value='';render();$('#shop').scrollIntoView({behavior:'smooth'})}if(b.id==='clear-brand'){brand='';render()}if(b.dataset.minus){cart[b.dataset.minus]--;if(!cart[b.dataset.minus])delete cart[b.dataset.minus];save()}if(b.dataset.plus){cart[b.dataset.plus]=Math.min(cart[b.dataset.plus]+1,99);save()}if(b.dataset.remove){delete cart[b.dataset.remove];save()}if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.hasAttribute('data-continue-shop')){cartDialog.close();if($('#shop'))$('#shop').scrollIntoView({behavior:'smooth'});else location.href='/shop/'}});
$('#search')?.addEventListener('input',e=>{query=e.target.value.toLowerCase().trim();render()});if($('#search-open'))$('#search-open').onclick=()=>{if(!$('#shop')){location.href='/shop/';return}$('#shop').scrollIntoView({behavior:'smooth'});$('#search').focus({preventScroll:true})};if($('#hero-detail'))$('#hero-detail').onclick=()=>detail('on');if($('#cart-open'))$('#cart-open').onclick=()=>{renderCart();cartDialog.showModal()};const nav=$('nav'),menuToggle=$('#menu-toggle'),shopNav=$('.shop-nav'),shopToggle=$('#shop-toggle'),shopMenu=$('#shop-categories');
function toggleShop(open){shopToggle.setAttribute('aria-expanded',String(open));shopMenu.hidden=!open;shopNav.classList.toggle('expanded',open)}
function toggleNav(open){nav.classList.toggle('open',open);menuToggle.setAttribute('aria-expanded',String(open));menuToggle.textContent=open?'×':'☰';if(!open)toggleShop(false)}
menuToggle.onclick=()=>toggleNav(!nav.classList.contains('open'));
shopToggle.onclick=()=>toggleShop(shopMenu.hidden);
shopNav.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&matchMedia('(min-width: 761px)').matches)toggleShop(true)});
shopNav.addEventListener('pointerleave',()=>{if(matchMedia('(min-width: 761px)').matches&&!shopNav.contains(document.activeElement))toggleShop(false)});
shopNav.addEventListener('focusout',e=>{if(!shopNav.contains(e.relatedTarget))toggleShop(false)});
document.addEventListener('click',e=>{if(!e.target.closest('header'))toggleNav(false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!shopMenu.hidden){toggleShop(false);shopToggle.focus()}else if(nav.classList.contains('open')){toggleNav(false);menuToggle.focus()}}});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>toggleNav(false)));
[productDialog,cartDialog].forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#year').textContent=new Date().getFullYear();render();save();

window.ssStore={products,add,openBag(){renderCart();cartDialog.showModal()}};

document.querySelectorAll("nav a").forEach(a=>{if(a.getAttribute("href")===location.pathname)a.setAttribute("aria-current","page")});
